async function main() {
  // Validate required env vars
  const required = ["SMTP_HOST", "SMTP_PORT", "SMTP_USER", "SMTP_PASS", "FROM_EMAIL"];
  const missing = required.filter((v) => !process.env[v]);
  if (missing.length) {
    console.error("❌ Missing required environment variables:", missing.join(", "));
    console.error("\nUsage:");
    console.error(
      "  SMTP_HOST=smtp.gmail.com SMTP_PORT=587 SMTP_USER=you@gmail.com SMTP_PASS=xxxx FROM_EMAIL=you@gmail.com node send_order_summary.js"
    );
    process.exit(1);
  }

  const transporter = nodemailer.createTransport({
    host: process.env.SMTP_HOST,
    port: Number(process.env.SMTP_PORT),
    secure: process.env.SMTP_SECURE === "true", // true for 465, false for 587/STARTTLS
    auth: {
      user: process.env.SMTP_USER,
      pass: process.env.SMTP_PASS,
    },
  });

  console.log(`📧 Sending order summary to ${TO_EMAIL} ...`);

  const info = await transporter.sendMail({
    from: process.env.FROM_EMAIL,
    to: TO_EMAIL,
    subject: SUBJECT,
    html: HTML_BODY,
  });

  console.log(`✅ Email sent! Message ID: ${info.messageId}`);
}

main().catch((err) => {
  console.error("❌ Failed to send email:", err.message);
  process.exit(1);
});
